param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop';$snapshotRoot=Join-Path $RepositoryRoot 'tests/e2e/frontend-operations-governance/snapshots';$outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/operations-governance-visual-baseline.json'
$snapshots=@(Get-ChildItem -LiteralPath $snapshotRoot -Filter 'PV-*.png'|Sort-Object Name);if($snapshots.Count -ne 34){throw "Expected exactly 34 governance snapshots, found $($snapshots.Count)."}
$cases=foreach($snapshot in $snapshots){$pv=[IO.Path]::GetFileNameWithoutExtension($snapshot.Name);$number=[int]$pv.Substring(3);$pageId=if($number -le 177){'operations.documents'}elseif($number -le 187){'operations.audit'}else{'operations.system-health'};[ordered]@{pv=$pv;pageId=$pageId;testId="operations-governance-visual.spec.ts::$pv";baselinePath=$snapshot.FullName.Substring($RepositoryRoot.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $snapshot.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$snapshot.Length}}
if(@($cases.sha256|Sort-Object -Unique).Count -ne 34){throw 'Governance snapshots must have 34 unique hashes.'}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-visual-regression-baseline';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();contractVersion='operations-governance-design-1.0';baselineVersion='operations-governance-windows-chromium-v1';environment=[ordered]@{operatingSystem='Windows';browser='Chromium';viewport='1440x900';locale='zh-CN';timezone='Asia/Shanghai';colorScheme='light';reducedMotion=$true};businessAssertions=@('Fuxing Bank operations console covers 34 document, audit-chain, and system-health states from PV-0164 through PV-0197.','Operations documents are stored in PostgreSQL with content bytes, SHA-256 checksum, lifecycle status, version, uploader, and immutable audit actions.','Audit verification recalculates every record hash and verifies previous-hash continuity before reporting CHAIN_OK.','System health combines dependency status and runtime-generated operational alerts through an authorized public contract.','Visual baselines follow the unified Fuxing Bank operations shell while retaining the source previews information hierarchy, filters, tables, status semantics, and dialogs.','Visual fixtures are deterministic synthetic data and contain no real personal data or secrets.');cases=$cases}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
